CREATE TABLE public.employee_loans(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL REFERENCES public.organizations(id) DEFAULT public.current_org_id(),user_id uuid NOT NULL,creditor_id uuid NOT NULL REFERENCES public.creditors(id),original_amount numeric NOT NULL CHECK(original_amount>0 AND original_amount<=100000000),balance numeric NOT NULL CHECK(balance>=0 AND balance<=original_amount),monthly_repayment numeric NOT NULL CHECK(monthly_repayment>0),is_active boolean NOT NULL DEFAULT true,notes text NOT NULL DEFAULT '' CHECK(length(notes)<=500),created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT ON public.employee_loans TO authenticated; GRANT ALL ON public.employee_loans TO service_role; ALTER TABLE public.employee_loans ENABLE ROW LEVEL SECURITY; CREATE POLICY company_loan_reads ON public.employee_loans FOR SELECT TO authenticated USING(org_id=public.current_org_id() AND (user_id=auth.uid() OR (public.is_admin_or_manager(auth.uid()) AND public.has_workspace_access(auth.uid(),'payroll')))); CREATE TRIGGER enforce_company_record BEFORE INSERT OR UPDATE ON public.employee_loans FOR EACH ROW EXECUTE FUNCTION public.enforce_company_record(); CREATE TRIGGER audit_company_changes AFTER INSERT OR UPDATE OR DELETE ON public.employee_loans FOR EACH ROW EXECUTE FUNCTION public.audit_company_changes();
CREATE TABLE public.loan_repayments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL REFERENCES public.organizations(id),loan_id uuid NOT NULL REFERENCES public.employee_loans(id),payroll_run_id uuid NOT NULL REFERENCES public.payroll_runs(id),user_id uuid NOT NULL,amount numeric NOT NULL CHECK(amount>0),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(loan_id,payroll_run_id)); GRANT SELECT ON public.loan_repayments TO authenticated; GRANT ALL ON public.loan_repayments TO service_role; ALTER TABLE public.loan_repayments ENABLE ROW LEVEL SECURITY; CREATE POLICY company_repayment_reads ON public.loan_repayments FOR SELECT TO authenticated USING(org_id=public.current_org_id() AND (user_id=auth.uid() OR (public.is_admin_or_manager(auth.uid()) AND public.has_workspace_access(auth.uid(),'payroll')))); CREATE TRIGGER enforce_company_record BEFORE INSERT OR UPDATE ON public.loan_repayments FOR EACH ROW EXECUTE FUNCTION public.enforce_company_record();
CREATE FUNCTION public.create_employee_loan(_employee uuid,_creditor uuid,_original numeric,_balance numeric,_monthly numeric,_notes text DEFAULT '') RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result uuid; BEGIN IF NOT public.is_admin_or_manager(auth.uid()) OR NOT public.has_workspace_access(auth.uid(),'payroll') THEN RAISE EXCEPTION 'Payroll management access required'; END IF; IF public.employee_org_id(_employee) IS DISTINCT FROM public.current_org_id() OR NOT EXISTS(SELECT 1 FROM public.creditors WHERE id=_creditor AND org_id=public.current_org_id()) THEN RAISE EXCEPTION 'Employee and creditor must belong to your company'; END IF; IF _original IS NULL OR _balance IS NULL OR _monthly IS NULL OR _original<=0 OR _original>100000000 OR _balance<0 OR _balance>_original OR _monthly<=0 OR _monthly>_original OR length(coalesce(_notes,''))>500 OR _original<>round(_original,2) OR _balance<>round(_balance,2) OR _monthly<>round(_monthly,2) THEN RAISE EXCEPTION 'Invalid loan amounts'; END IF; INSERT INTO public.employee_loans(user_id,creditor_id,original_amount,balance,monthly_repayment,notes,org_id,is_active) VALUES(_employee,_creditor,_original,_balance,_monthly,coalesce(_notes,''),public.current_org_id(),_balance>0) RETURNING id INTO result; RETURN result; END $$; REVOKE ALL ON FUNCTION public.create_employee_loan(uuid,uuid,numeric,numeric,numeric,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.create_employee_loan(uuid,uuid,numeric,numeric,numeric,text) TO authenticated;
CREATE FUNCTION public.set_employee_loan_active(_loan uuid,_active boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_admin_or_manager(auth.uid()) OR NOT public.has_workspace_access(auth.uid(),'payroll') THEN RAISE EXCEPTION 'Payroll management access required'; END IF; IF _active IS NULL THEN RAISE EXCEPTION 'Choose loan status'; END IF; UPDATE public.employee_loans SET is_active=_active WHERE id=_loan AND org_id=public.current_org_id() AND (NOT _active OR balance>0); IF NOT FOUND THEN RAISE EXCEPTION 'Loan not found or already repaid'; END IF; END $$; REVOKE ALL ON FUNCTION public.set_employee_loan_active(uuid,boolean) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.set_employee_loan_active(uuid,boolean) TO authenticated;
CREATE FUNCTION public.apply_payroll_loans(_run uuid,_employee uuid,_factor numeric,_submitted numeric) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE l public.employee_loans; repayment numeric; expected numeric:=0; recurring numeric:=0; BEGIN
IF NOT public.is_admin_or_manager(auth.uid()) OR NOT public.has_workspace_access(auth.uid(),'payroll') OR public.employee_org_id(_employee) IS DISTINCT FROM public.current_org_id() OR NOT EXISTS(SELECT 1 FROM public.payroll_runs WHERE id=_run AND org_id=public.current_org_id()) THEN RAISE EXCEPTION 'Company payroll access required'; END IF;
FOR l IN SELECT * FROM public.employee_loans WHERE user_id=_employee AND org_id=public.current_org_id() AND is_active AND balance>0 ORDER BY id FOR UPDATE LOOP repayment:=least(l.balance,round(l.monthly_repayment*_factor,2)); expected:=expected+repayment; IF repayment>0 THEN INSERT INTO public.loan_repayments(org_id,loan_id,payroll_run_id,user_id,amount) VALUES(l.org_id,l.id,_run,_employee,repayment); UPDATE public.employee_loans SET balance=balance-repayment,is_active=(balance-repayment>0) WHERE id=l.id; END IF; END LOOP;
IF _submitted IS NULL OR abs(_submitted-expected)>0.01 THEN RAISE EXCEPTION 'Loan balance changed; refresh payroll'; END IF;
END $$; REVOKE ALL ON FUNCTION public.apply_payroll_loans(uuid,uuid,numeric,numeric) FROM PUBLIC,authenticated,anon; GRANT EXECUTE ON FUNCTION public.apply_payroll_loans(uuid,uuid,numeric,numeric) TO service_role;
-- Called only inside the existing atomic payroll approval boundary; any repayment failure rolls back the entire run.
DO $$ DECLARE func record; definition text; factor text; BEGIN FOR func IN SELECT oid,proname FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname IN ('approve_payroll_run','approve_department_payroll') LOOP definition:=pg_get_functiondef(func.oid); factor:=CASE WHEN func.proname='approve_payroll_run' THEN 'f' ELSE '1' END; definition:=replace(definition,'END LOOP; RETURN run;',format('PERFORM public.apply_payroll_loans(run,p.user_id,%s,coalesce((row->>''loan_deductions'')::numeric,0)); END LOOP; RETURN run;',factor)); EXECUTE definition; END LOOP; END $$;
COMMENT ON TABLE public.employee_loans IS 'Loan balances decrease only with atomic payroll deductions; this does not represent creditor remittance or bank payment.';